// Independent PLAY-04 fix re-audit: real gateway child process, real PostgreSQL, real match client and real time.
// D1: an opening-phase waiting concession lease held while the active client uses its default retry settings.
// D2: the waiting client repeatedly concedes (stock client) during each opening step; count active-client busy receipts.
import { qualification, until } from './apps/match-service/tests/client-fixtures.mjs';
import { createClockRepository } from './packages/db/dist/index.js';
import { validateSubmission } from './apps/match-service/dist/validation.js';

const clock = { schemaVersion: 1, id: 'audit-budget', profile: 'qualification', mode: 'dynamic', initialReserveMs: 150000, reserveCapMs: 150000, perActionBonusMs: 5000, perTurnPassBonusMs: 60000, resetTimeOnSkipMs: 60000, graceMs: 0 };
const out = {};
const tryRun = async (name, work) => { try { await work(); } catch (error) { out[name + 'Error'] = String(error && error.stack || error); } };

await tryRun('D1', async () => {
  const f = await qualification('http://localhost:5173', { clock }), repo = createClockRepository('test'); let owner;
  try {
    const host = await f.host(), clients = f.players.map((_, i) => f.client(i, host.url, { retryBaseMs: 250 }));
    await Promise.all(clients.map(c => c.connect()));
    const chooser = f.players.indexOf(clients[0].view.priorityId), waiting = 1 - chooser;
    const held = await repo.reservePlayer(validateSubmission(f.players[waiting], { matchId: f.id, commandId: 'audit-held-opening-concession', expectedVersion: 0, move: 'concede', input: {} }));
    out.D1_waitingOpeningConcessionAdmission = held.kind; owner = held.reservation;
    const sockets = f.sockets[chooser].length, start = f.receipts[chooser].length, t0 = performance.now();
    const outcome = await clients[chooser].submit({ kind: 'chooseWhoGoesFirst', input: { playerId: f.players[0] } }).then(r => 'resolved ' + r.outcome, e => 'rejected ' + (e.code ?? e.message));
    out.D1_activeClientWhileLeaseHeld = { outcome, elapsedMs: Math.round(performance.now() - t0), busyReceipts: f.receipts[chooser].slice(start).filter(r => r.outcome === 'rate_limited').length, maintenanceReceipts: f.receipts[chooser].slice(start).filter(r => r.outcome === 'maintenance').length, newSockets: f.sockets[chooser].length - sockets, clientStatus: clients[chooser].status };
    await repo.abort(owner); owner = undefined;
    const served = await f.creator.view(f.players[chooser], { matchId: f.id });
    out.D1_afterRelease = { stateVersion: served.stateVersion, clockStatus: (await f.creator.readClock(f.players[chooser], { matchId: f.id })).status };
  } finally { if (owner) await repo.abort(owner).catch(() => {}); await f.close(); await repo.close(); }
});

await tryRun('D2', async () => {
  const f = await qualification('http://localhost:5173', { clock });
  try {
    const host = await f.host(), clients = f.players.map((_, i) => f.client(i, host.url, { retryBaseMs: 250 }));
    await Promise.all(clients.map(c => c.connect()));
    const steps = [];
    for (let step = 0; step < 3; step++) {
      const view = clients[0].view, activeId = view.priorityId, active = f.players.indexOf(activeId), waiting = 1 - active;
      const intent = step === 0 ? { kind: 'chooseWhoGoesFirst', input: { playerId: f.players[0] } } : { kind: 'alterHand', input: { cardsToMulligan: [] } };
      let stop = false; const spam = {};
      const attacker = (async () => {
        while (!stop) {
          try { await until(() => stop || clients[waiting].status === 'ready', 5000); } catch { spam.notReady = (spam.notReady ?? 0) + 1; break; }
          if (stop) break;
          const x = await clients[waiting].submit({ kind: 'concede', input: {} }).then(r => r.outcome + '/' + r.reason, e => 'client ' + e.code);
          spam[x] = (spam[x] ?? 0) + 1; if (x.startsWith('client closed')) break;
        }
      })();
      await new Promise(r => setTimeout(r, 400));
      const start = f.receipts[active].length, t0 = performance.now();
      await until(() => clients[active].status === 'ready', 5000);
      const outcome = await clients[active].submit(intent).then(r => r.outcome, e => 'client ' + e.code);
      const elapsedMs = Math.round(performance.now() - t0); stop = true; await attacker;
      steps.push({ step, outcome, elapsedMs, activeBusyReceipts: f.receipts[active].slice(start).filter(r => r.outcome === 'rate_limited').length, waitingConcessions: spam });
      if (outcome !== 'accepted') break;
      await until(() => clients.every(c => c.status === 'ready' && c.view?.stateVersion >= step + 1), 10000);
    }
    out.D2_openingSteps = steps;
  } finally { await f.close(); }
});
console.log(JSON.stringify(out, null, 1));
